CREATE TABLE files (id CHAR(36) PRIMARY KEY,tenant_id VARCHAR(191) NOT NULL,owner_id VARCHAR(191) NOT NULL,bucket VARCHAR(191) NOT NULL,object_key VARCHAR(512) NOT NULL,filename TEXT NOT NULL,content_type VARCHAR(191) NOT NULL,size BIGINT NOT NULL,checksum_sha256 CHAR(64) NOT NULL,status VARCHAR(32) NOT NULL,scan_status VARCHAR(32) NOT NULL,idempotency_key VARCHAR(191) NOT NULL,version BIGINT NOT NULL DEFAULT 1,created_at DATETIME(6) NOT NULL,updated_at DATETIME(6) NOT NULL,created_by TEXT NOT NULL,updated_by TEXT NOT NULL,UNIQUE KEY files_object_uq(bucket,object_key),UNIQUE KEY files_idempotency_uq(tenant_id,idempotency_key),INDEX files_tenant_owner_idx(tenant_id,owner_id,created_at DESC),INDEX files_lifecycle_idx(status,updated_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
